        const frogPixelX = frog.x * CELL_SIZE;
        const frogPixelY = frog.y * CELL_SIZE;
        if (frogPixelX + frog.width < frog.onLog.x || frogPixelX > frog.onLog.x + frog.onLog.width) {
            frog.onLog = null;
        }
        // Check if frog is off screen from log movement
        if (frog.x < 0 || frog.x >= COLS) {
            frogDrown();
        }
    }

    // Check car collision
    const frogPixelX = frog.x * CELL_SIZE + (CELL_SIZE - frog.width)/2;
    const frogPixelY = frog.y * CELL_SIZE + (CELL_SIZE - frog.height)/2;
    for (const car of cars) {
        if (
            frogPixelX < car.x + car.width &&
            frogPixelX + frog.width > car.x &&
            frogPixelY < car.y + car.height &&
            frogPixelY + frog.height > car.y
        ) {
            frogDie();
            return;
        }
    }

    // Check river collision
    if (RIVER_LANES.includes(frog.y)) {
        let onObject = false;
        for (const obj of riverObjects) {
            // Check if frog is on the object (same row, overlapping x)
            if (obj.y === frog.y * CELL_SIZE + (CELL_SIZE - obj.height)/2) {
                const objLeft = obj.x;
                const objRight = obj.x + obj.width;
                const frogLeft = frogPixelX;
                const frogRight = frogPixelX + frog.width;
                if (frogLeft >= objLeft && frogRight <= objRight) {
                    if (obj.type === 'turtle' && obj.isSunk) {
                        // Frog is on sunk turtle, drown
                        frogDrown();
                        return;
                    }
                    onObject = true;
                    frog.onLog = obj;
                    break;
                }
            }
        }
        if (!onObject) {
            frogDrown();
            return;
        }
    }

    // Check win condition
    if (frog.y === TOP_SAFE_ROW) {
        score += 100;
        playSound('win');
        resetFrog();
        updateUI();
    }
}

