function draw() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw background zones
    // Top safe zone (row 0): light green
    ctx.fillStyle = '#90ee90';
    ctx.fillRect(0, 0, canvas.width, CELL_SIZE);
    // Road lanes (rows1-5): gray
    ctx.fillStyle = '#696969';
    for (let row = 1; row <=5; row++) {
        ctx.fillRect(0, row * CELL_SIZE, canvas.width, CELL_SIZE);
    }
    // Median (row6): brown
    ctx.fillStyle = '#8b4513';
    ctx.fillRect(0, MEDIAN_ROW * CELL_SIZE, canvas.width, CELL_SIZE);
    // River lanes (rows7-11): blue
    ctx.fillStyle = '#1e90ff';
    for (let row =7; row <=11; row++) {
        ctx.fillRect(0, row * CELL_SIZE, canvas.width, CELL_SIZE);
    }
    // Bottom safe zone (row12): light green
    ctx.fillStyle = '#90ee90';
    ctx.fillRect(0, BOTTOM_SAFE_ROW * CELL_SIZE, canvas.width, CELL_SIZE);

    // Draw road lane lines (dashed white lines)
    ctx.fillStyle = '#fff';
    for (let row =1; row <=5; row++) {
        const y = row * CELL_SIZE + CELL_SIZE/2 - 2;
        for (let x=0; x < canvas.width; x+=20) {
            ctx.fillRect(x, y, 10, 4);
        }
    }

    // Draw median line
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, MEDIAN_ROW * CELL_SIZE + CELL_SIZE/2 -2, canvas.width,4);

    // Draw river lane lines? Maybe not, keep it simple.

    // Draw cars
    cars.forEach(car => {
        ctx.fillStyle = car.color;
        // Draw car body
        ctx.fillRect(car.x, car.y, car.width, car.height);
        // Draw car details: windows, wheels
        ctx.fillStyle = '#000';
        // Windows
        ctx.fillRect(car.x + 5, car.y + 5, car.width -10, 8);
        // Wheels
        ctx.fillRect(car.x + 5, car.y + car.height -5, 8, 5);
        ctx.fillRect(car.x + car.width -13, car.y + car.height -5, 8,5);
    });

    // Draw river objects
    riverObjects.forEach(obj => {
        if (obj.type === 'log') {
            ctx.fillStyle = '#8b4513'; // Brown
            ctx.fillRect(obj.x, obj.y, obj.width, obj.height);
            // Log details: darker lines
            ctx.fillStyle = '#654321';
            ctx.fillRect(obj.x +5, obj.y +5, obj.width -10, 4);
            ctx.fillRect(obj.x +5, obj.y + obj.height -9, obj.width -10,4);
        } else { // Turtle
            if (obj.isSunk) {
                // Draw sunk turtle as darker green, partially submerged
                ctx.fillStyle = '#006400';
                ctx.beginPath();
                ctx.arc(obj.x + obj.width/2, obj.y + obj.height/2 + 5, obj.width/2, 0, Math.PI*2);
                ctx.fill();
            } else {
                ctx.fillStyle = '#00ff00'; // Bright green
                ctx.beginPath();
                ctx.arc(obj.x + obj.width/2, obj.y + obj.height/2, obj.width/2, 0, Math.PI*2);
                ctx.fill();
                // Turtle details: eyes, shell lines
                ctx.fillStyle = '#000';
                ctx.fillRect(obj.x + obj.width/2 -2, obj.y + obj.height/2 -5, 4,4); // Eyes
                ctx.fillStyle = '#008000';
                ctx.fillRect(obj.x + obj.width/2 -5, obj.y + obj.height/2, 10, 2); // Shell line
            }
        }
    });

    // Draw frog
    const frogPixelX = frog.x * CELL_SIZE + (CELL_SIZE - frog.width)/2;
    const frogPixelY = frog.y * CELL_SIZE + (CELL_SIZE - frog.height)/2;
    ctx.fillStyle = frog.color;
    // Frog body
    ctx.fillRect(frogPixelX, frogPixelY, frog.width, frog.height);
    // Frog eyes: white with black pupils
    ctx.fillStyle = '#fff';
    ctx.fillRect(frogPixelX + 5, frogPixelY +5, 8,8);
    ctx.fillRect(frogPixelX + frog.width -13, frogPixelY +5, 8,8);
    ctx.fillStyle = '#000';
    ctx.fillRect(frogPixelX +7, frogPixelY +7, 4,4);
    ctx.fillRect(frogPixelX + frog.width -11, frogPixelY +7,4,4);
    // Frog mouth
    ctx.fillRect(frogPixelX + frog.width/2 -3, frogPixelY + frog.height -8, 6,2);

    // Draw game over text if needed
    if (gameOver) {
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        ctx.fillRect(0, canvas.height/2 - 40, canvas.width, 80);
        ctx.fillStyle = '#ff0000';
        ctx.font = '30px Courier New';
        ctx.textAlign = 'center';
        ctx.fillText('GAME OVER', canvas.width/2, canvas.height/2 + 10);
        ctx.fillStyle = '#fff';
        ctx.font = '20px Courier New';
        ctx.fillText('Score: ' + score, canvas.width/2, canvas.height/2 + 35);
    }
}

